const menu = { soup: 6 };

const priced = new Proxy(menu, {
  get(target, key, receiver) {
    return key in target ? Reflect.get(target, key, receiver) : "ask";
  },
  set(target, key, value, receiver) {
    return Reflect.set(target, key, value * 2, receiver);
  },
});

priced.salad = 4;

console.log(priced.soup, priced.salad, priced.cake);
console.log(menu.salad);
console.log(Object.keys(priced).join(","));
